CREATE TYPE public.app_role AS ENUM ('user','admin');
CREATE TYPE public.tx_type AS ENUM ('credit','debit');
CREATE TYPE public.tx_status AS ENUM ('pending','success','failed','reversed');
CREATE TYPE public.payment_provider AS ENUM ('neurapay','manual');
CREATE TYPE public.order_status AS ENUM ('pending','completed','pending_credentials','failed','refunded');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text,display_name text,avatar_url text,phone text,suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name,avatar_url,phone) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'user',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon,authenticated,service_role;
CREATE POLICY roles_read_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_read_self ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update_self ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.wallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,balance numeric(14,2) NOT NULL DEFAULT 0 CHECK(balance>=0),currency text NOT NULL DEFAULT 'NGN',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wallets TO authenticated; GRANT ALL ON public.wallets TO service_role; ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallets_read_self ON public.wallets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.wallet_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wallet_id uuid NOT NULL REFERENCES public.wallets(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,type public.tx_type NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>0),balance_after numeric(14,2) NOT NULL,status public.tx_status NOT NULL DEFAULT 'success',provider public.payment_provider,reference text UNIQUE,description text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wallet_transactions TO authenticated; GRANT ALL ON public.wallet_transactions TO service_role; ALTER TABLE public.wallet_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transactions_read_self ON public.wallet_transactions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX wallet_transactions_user_created_idx ON public.wallet_transactions(user_id,created_at DESC);
CREATE TABLE public.payment_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,provider public.payment_provider NOT NULL,reference text NOT NULL UNIQUE,provider_reference text,amount numeric(14,2) NOT NULL CHECK(amount>0),currency text NOT NULL DEFAULT 'NGN',status public.tx_status NOT NULL DEFAULT 'pending',raw jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_intents TO authenticated; GRANT ALL ON public.payment_intents TO service_role; ALTER TABLE public.payment_intents ENABLE ROW LEVEL SECURITY;
CREATE POLICY payment_intents_read_self ON public.payment_intents FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX payment_intents_user_created_idx ON public.payment_intents(user_id,created_at DESC);
CREATE TABLE public.product_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,slug text NOT NULL UNIQUE,description text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_categories TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.product_categories TO authenticated; GRANT ALL ON public.product_categories TO service_role; ALTER TABLE public.product_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_public_read ON public.product_categories FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY categories_admin_write ON public.product_categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES public.product_categories(id) ON DELETE SET NULL,title text NOT NULL,slug text NOT NULL UNIQUE,description text,price numeric(14,2) NOT NULL CHECK(price>0),currency text NOT NULL DEFAULT 'NGN',stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),image_url text,published boolean NOT NULL DEFAULT false,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_public_read ON public.products FOR SELECT TO anon,authenticated USING(published OR public.has_role(auth.uid(),'admin'));
CREATE POLICY products_admin_write ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX products_public_idx ON public.products(published,created_at DESC);
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,total numeric(14,2) NOT NULL CHECK(total>=0),currency text NOT NULL DEFAULT 'NGN',status public.order_status NOT NULL DEFAULT 'pending',wallet_tx_id uuid REFERENCES public.wallet_transactions(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_read_self ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY orders_admin_update ON public.orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX orders_user_created_idx ON public.orders(user_id,created_at DESC);
CREATE TABLE public.order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,title text NOT NULL,unit_price numeric(14,2) NOT NULL,quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0),delivered_payload text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role; ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_read_owner ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND(o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.product_credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,content text NOT NULL,username text,password text,email text,email_password text,two_factor text,label text,order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL,assigned_to uuid REFERENCES public.profiles(id) ON DELETE SET NULL,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_credentials TO authenticated; GRANT ALL ON public.product_credentials TO service_role; ALTER TABLE public.product_credentials ENABLE ROW LEVEL SECURITY;
CREATE POLICY credentials_read_assigned ON public.product_credentials FOR SELECT TO authenticated USING(assigned_to=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX credentials_available_idx ON public.product_credentials(product_id) WHERE order_id IS NULL;
CREATE TABLE public.site_settings(key text PRIMARY KEY,value jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role; ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_admin_access ON public.site_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.activity_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,action text NOT NULL,target text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role; ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_logs_admin_read ON public.activity_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.ensure_user_wallet() RETURNS TABLE(id uuid,balance numeric,currency text,updated_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_user_id uuid:=auth.uid(); BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.profiles(id,email,display_name) VALUES(v_user_id,auth.jwt()->>'email',COALESCE(auth.jwt()->'user_metadata'->>'display_name',split_part(COALESCE(auth.jwt()->>'email',''),'@',1))) ON CONFLICT(id) DO UPDATE SET email=EXCLUDED.email,updated_at=now(); INSERT INTO public.wallets(user_id) VALUES(v_user_id) ON CONFLICT(user_id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(v_user_id,'user') ON CONFLICT(user_id,role) DO NOTHING; RETURN QUERY SELECT w.id,w.balance,w.currency,w.updated_at FROM public.wallets w WHERE w.user_id=v_user_id; END $$;
REVOKE ALL ON FUNCTION public.ensure_user_wallet() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ensure_user_wallet() TO authenticated;
CREATE FUNCTION public.purchase_with_wallet(_product_id uuid,_quantity integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); p public.products; w public.wallets; total numeric; tx uuid; ord uuid; ids uuid[]; delivery text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND suspended) THEN RAISE EXCEPTION 'Account suspended'; END IF; IF _quantity IS NULL OR _quantity<1 OR _quantity>20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO p FROM public.products WHERE id=_product_id AND published FOR UPDATE; IF NOT FOUND OR p.stock<_quantity THEN RAISE EXCEPTION 'Product is unavailable'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=u FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; IF w.currency<>p.currency THEN RAISE EXCEPTION 'Currency mismatch'; END IF; total:=p.price*_quantity; IF w.balance<total THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF; SELECT array_agg(c.id) INTO ids FROM(SELECT id FROM public.product_credentials WHERE product_id=_product_id AND order_id IS NULL ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT _quantity)c; IF COALESCE(cardinality(ids),0)<_quantity THEN RAISE EXCEPTION 'Product is currently out of stock'; END IF; UPDATE public.wallets SET balance=balance-total,updated_at=now() WHERE id=w.id RETURNING balance INTO w.balance; UPDATE public.products SET stock=stock-_quantity,updated_at=now() WHERE id=p.id; INSERT INTO public.wallet_transactions(wallet_id,user_id,type,amount,balance_after,status,provider,reference,description) VALUES(w.id,u,'debit',total,w.balance,'success','manual','purchase-'||gen_random_uuid()::text,'Purchase: '||p.title) RETURNING id INTO tx; INSERT INTO public.orders(user_id,total,currency,status,wallet_tx_id) VALUES(u,total,p.currency,'completed',tx) RETURNING id INTO ord; UPDATE public.product_credentials SET order_id=ord,assigned_to=u,delivered_at=now() WHERE id=ANY(ids); SELECT string_agg(content,E'\n---\n' ORDER BY created_at) INTO delivery FROM public.product_credentials WHERE id=ANY(ids); INSERT INTO public.order_items(order_id,product_id,title,unit_price,quantity,delivered_payload) VALUES(ord,p.id,p.title,p.price,_quantity,delivery); RETURN ord; END $$;
REVOKE ALL ON FUNCTION public.purchase_with_wallet(uuid,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.purchase_with_wallet(uuid,integer) TO authenticated;
CREATE FUNCTION public.settle_neurapay_payment(_reference text,_amount numeric,_provider_reference text DEFAULT NULL,_provider_data jsonb DEFAULT '{}') RETURNS TABLE(credited boolean,already_credited boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.payment_intents; w public.wallets; b numeric; BEGIN SELECT * INTO i FROM public.payment_intents WHERE reference=_reference AND provider='neurapay' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Payment intent not found'; END IF; IF i.status='success' THEN RETURN QUERY SELECT false,true; RETURN; END IF; IF i.status<>'pending' OR _amount IS NULL OR _amount<>i.amount OR _amount<=0 THEN RAISE EXCEPTION 'Invalid settlement'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=i.user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; UPDATE public.wallets SET balance=balance+_amount,updated_at=now() WHERE id=w.id RETURNING balance INTO b; UPDATE public.payment_intents SET status='success',provider_reference=COALESCE(_provider_reference,provider_reference),raw=raw||jsonb_build_object('settlement',_provider_data),updated_at=now() WHERE id=i.id; INSERT INTO public.wallet_transactions(wallet_id,user_id,type,amount,balance_after,status,provider,reference,description,metadata) VALUES(w.id,i.user_id,'credit',_amount,b,'success','neurapay',_reference,'Wallet funded via NeuraPay',jsonb_build_object('provider_reference',_provider_reference)); RETURN QUERY SELECT true,false; END $$;
REVOKE ALL ON FUNCTION public.settle_neurapay_payment(text,numeric,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.settle_neurapay_payment(text,numeric,text,jsonb) TO service_role;